"use strict";const t=require("./request.js");exports.loginByPassword=function(e){return t.request({url:"/api/auth/login",method:"POST",data:e})},exports.loginBySms=function(e){return t.request({url:"/api/auth/login/sms",method:"POST",data:e})},exports.register=function(e){return t.request({url:"/api/auth/register",method:"POST",data:e})},exports.resetPassword=function(e){return t.request({url:"/api/auth/password/reset",method:"POST",data:e})},exports.sendSmsCode=function(e){return t.request({url:"/api/auth/sms/send",method:"POST",data:e})};
